60	void LRUFileCache::useCell(
61	    const FileSegmentCell & cell, FileSegments & result, std::lock_guard<std::mutex> & cache_lock)
62	{
63	    auto file_segment = cell.file_segment;
64	
65	    if (file_segment->isDownloaded()
66	        && fs::file_size(getPathInLocalCache(file_segment->key(), file_segment->offset(), file_segment->isPersistent())) == 0)
67	        throw Exception(ErrorCodes::LOGICAL_ERROR,
68	                        "Cannot have zero size downloaded file segments. Current file segment: {}",
69	                        file_segment->range().toString());
70	
71	    result.push_back(cell.file_segment);
72	
73	    /**
74	     * A cell receives a queue iterator on first successful space reservation attempt
75	     * (space is reserved incrementally on each read buffer nextImpl() call).
76	     */
77	    if (cell.queue_iterator)
78	    {
79	        /// Move to the end of the queue. The iterator remains valid.
80	        queue.moveToEnd(*cell.queue_iterator, cache_lock);
81	    }
82	}
