84	LRUFileCache::FileSegmentCell * LRUFileCache::getCell(
85	    const Key & key, size_t offset, std::lock_guard<std::mutex> & /* cache_lock */)
86	{
87	    auto it = files.find(key);
88	    if (it == files.end())
89	        return nullptr;
90	
91	    auto & offsets = it->second;
92	    auto cell_it = offsets.find(offset);
93	    if (cell_it == offsets.end())
94	        return nullptr;
95	
96	    return &cell_it->second;
