99	FileSegments LRUFileCache::getImpl(
100	    const Key & key, const FileSegment::Range & range, std::lock_guard<std::mutex> & cache_lock)
101	{
102	    /// Given range = [left, right] and non-overlapping ordered set of file segments,
103	    /// find list [segment1, ..., segmentN] of segments which intersect with given range.
104	
105	    auto it = files.find(key);
106	    if (it == files.end())
107	        return {};
108	
109	    const auto & file_segments = it->second;
110	    if (file_segments.empty())
111	    {
112	        auto key_path = getPathInLocalCache(key);
113	
114	        files.erase(key);
115	
116	        /// Note: it is guaranteed that there is no concurrency with files deletion,
117	        /// because cache files are deleted only inside IFileCache and under cache lock.
118	        if (fs::exists(key_path))
119	            fs::remove_all(key_path);
120	
121	        return {};
122	    }
123	
124	    FileSegments result;
125	    auto segment_it = file_segments.lower_bound(range.left);
126	    if (segment_it == file_segments.end())
127	    {
128	        /// N - last cached segment for given file key, segment{N}.offset < range.left:
129	        ///   segment{N}                       segment{N}
130	        /// [________                         [_______]
131	        ///     [__________]         OR                  [________]
132	        ///     ^                                        ^
133	        ///     range.left                               range.left
134	
135	        const auto & cell = file_segments.rbegin()->second;
136	        if (cell.file_segment->range().right < range.left)
137	            return {};
138	
139	        useCell(cell, result, cache_lock);
140	    }
141	    else /// segment_it <-- segmment{k}
142	    {
143	        if (segment_it != file_segments.begin())
144	        {
145	            const auto & prev_cell = std::prev(segment_it)->second;
146	            const auto & prev_cell_range = prev_cell.file_segment->range();
147	
148	            if (range.left <= prev_cell_range.right)
149	            {
150	                ///   segment{k-1}  segment{k}
151	                ///   [________]   [_____
152	                ///       [___________
153	                ///       ^
154	                ///       range.left
155	
156	                useCell(prev_cell, result, cache_lock);
157	            }
158	        }
159	
160	        ///  segment{k} ...       segment{k-1}  segment{k}                      segment{k}
161	        ///  [______              [______]     [____                        [________
162	        ///  [_________     OR              [________      OR    [______]   ^
163	        ///  ^                              ^                           ^   segment{k}.offset
164	        ///  range.left                     range.left                  range.right
165	
166	        while (segment_it != file_segments.end())
167	        {
168	            const auto & cell = segment_it->second;
169	            if (range.right < cell.file_segment->range().left)
170	                break;
171	
172	            useCell(cell, result, cache_lock);
173	            ++segment_it;
174	        }
175	    }
176	
177	    return result;
178	}
