180	FileSegments LRUFileCache::splitRangeIntoCells(
181	    const Key & key, size_t offset, size_t size, FileSegment::State state, bool is_persistent, std::lock_guard<std::mutex> & cache_lock)
182	{
183	    assert(size > 0);
184	
185	    auto current_pos = offset;
186	    auto end_pos_non_included = offset + size;
187	
188	    size_t current_cell_size;
189	    size_t remaining_size = size;
190	
191	    FileSegments file_segments;
192	    while (current_pos < end_pos_non_included)
193	    {
194	        current_cell_size = std::min(remaining_size, max_file_segment_size);
195	        remaining_size -= current_cell_size;
196	
197	        auto * cell = addCell(key, current_pos, current_cell_size, state, is_persistent, cache_lock);
198	        if (cell)
199	            file_segments.push_back(cell->file_segment);
200	        assert(cell);
201	
202	        current_pos += current_cell_size;
203	    }
204	
205	    assert(file_segments.empty() || offset + size - 1 == file_segments.back()->range().right);
206	    return file_segments;
207	}
