209	void LRUFileCache::fillHolesWithEmptyFileSegments(
210	    FileSegments & file_segments,
211	    const Key & key,
212	    const FileSegment::Range & range,
213	    bool fill_with_detached_file_segments,
214	    bool is_persistent,
215	    std::lock_guard<std::mutex> & cache_lock)
216	{
217	    /// There are segments [segment1, ..., segmentN]
218	    /// (non-overlapping, non-empty, ascending-ordered) which (maybe partially)
219	    /// intersect with given range.
220	
221	    /// It can have holes:
222	    /// [____________________]         -- requested range
223	    ///     [____]  [_]   [_________]  -- intersecting cache [segment1, ..., segmentN]
224	    ///
225	    /// For each such hole create a cell with file segment state EMPTY.
226	
227	    auto it = file_segments.begin();
228	    auto segment_range = (*it)->range();
229	
230	    size_t current_pos;
231	    if (segment_range.left < range.left)
232	    {
233	        ///    [_______     -- requested range
234	        /// [_______
235	        /// ^
236	        /// segment1
237	
238	        current_pos = segment_range.right + 1;
239	        ++it;
240	    }
241	    else
242	        current_pos = range.left;
243	
244	    while (current_pos <= range.right && it != file_segments.end())
245	    {
246	        segment_range = (*it)->range();
247	
248	        if (current_pos == segment_range.left)
249	        {
250	            current_pos = segment_range.right + 1;
251	            ++it;
252	            continue;
253	        }
254	
255	        assert(current_pos < segment_range.left);
256	
257	        auto hole_size = segment_range.left - current_pos;
258	
259	        if (fill_with_detached_file_segments)
260	        {
261	            auto file_segment = std::make_shared<FileSegment>(current_pos, hole_size, key, this, FileSegment::State::EMPTY);
262	            {
263	                std::lock_guard segment_lock(file_segment->mutex);
264	                file_segment->markAsDetached(segment_lock);
265	            }
266	            file_segments.insert(it, file_segment);
267	        }
268	        else
269	        {
270	            file_segments.splice(it, splitRangeIntoCells(key, current_pos, hole_size, FileSegment::State::EMPTY, is_persistent, cache_lock));
271	        }
272	
273	        current_pos = segment_range.right + 1;
274	        ++it;
275	    }
276	
277	    if (current_pos <= range.right)
278	    {
279	        ///   ________]     -- requested range
280	        ///   _____]
281	        ///        ^
282	        /// segmentN
283	
284	        auto hole_size = range.right - current_pos + 1;
285	
286	        if (fill_with_detached_file_segments)
287	        {
288	            auto file_segment = std::make_shared<FileSegment>(current_pos, hole_size, key, this, FileSegment::State::EMPTY);
289	            {
290	                std::lock_guard segment_lock(file_segment->mutex);
291	                file_segment->markAsDetached(segment_lock);
292	            }
293	            file_segments.insert(file_segments.end(), file_segment);
294	        }
295	        else
296	        {
297	            file_segments.splice(
298	                file_segments.end(), splitRangeIntoCells(key, current_pos, hole_size, FileSegment::State::EMPTY, is_persistent, cache_lock));
299	        }
300	    }
301	}
