303	FileSegmentsHolder LRUFileCache::getOrSet(const Key & key, size_t offset, size_t size, bool is_persistent)
304	{
305	    assertInitialized();
306	
307	    FileSegment::Range range(offset, offset + size - 1);
308	
309	    std::lock_guard cache_lock(mutex);
310	
311	#ifndef NDEBUG
312	    assertCacheCorrectness(key, cache_lock);
313	#endif
314	
315	    /// Get all segments which intersect with the given range.
316	    auto file_segments = getImpl(key, range, cache_lock);
317	
318	    if (file_segments.empty())
319	    {
320	        file_segments = splitRangeIntoCells(key, offset, size, FileSegment::State::EMPTY, is_persistent, cache_lock);
321	    }
322	    else
323	    {
324	        fillHolesWithEmptyFileSegments(file_segments, key, range, /* fill_with_detached */false, is_persistent, cache_lock);
325	    }
326	
327	    assert(!file_segments.empty());
328	    return FileSegmentsHolder(std::move(file_segments));
