363	LRUFileCache::FileSegmentCell * LRUFileCache::addCell(
364	    const Key & key, size_t offset, size_t size,
365	    FileSegment::State state, bool is_persistent,
366	    std::lock_guard<std::mutex> & cache_lock)
367	{
368	    /// Create a file segment cell and put it in `files` map by [key][offset].
369	
370	    if (!size)
371	        return nullptr; /// Empty files are not cached.
372	
373	    if (files[key].contains(offset))
374	        throw Exception(
375	            ErrorCodes::LOGICAL_ERROR,
376	            "Cache already exists for key: `{}`, offset: {}, size: {}.\nCurrent cache structure: {}",
377	            key.toString(), offset, size, dumpStructureUnlocked(key, cache_lock));
378	
379	    auto skip_or_download = [&]() -> FileSegmentPtr
380	    {
381	        FileSegment::State result_state = state;
382	        if (state == FileSegment::State::EMPTY && enable_cache_hits_threshold)
383	        {
384	            auto record = records.find({key, offset});
385	
386	            if (record == records.end())
387	            {
388	                auto queue_iter = stash_queue.add(key, offset, 0, cache_lock);
389	                records.insert({{key, offset}, queue_iter});
390	
391	                if (stash_queue.getElementsNum(cache_lock) > max_stash_element_size)
392	                {
393	                    auto remove_queue_iter = stash_queue.begin();
394	                    records.erase({remove_queue_iter->key, remove_queue_iter->offset});
395	                    stash_queue.remove(remove_queue_iter, cache_lock);
396	                }
397	
398	                /// For segments that do not reach the download threshold, we do not download them, but directly read them
399	                result_state = FileSegment::State::SKIP_CACHE;
400	            }
401	            else
402	            {
403	                auto queue_iter = record->second;
404	                queue_iter->hits++;
405	                stash_queue.moveToEnd(queue_iter, cache_lock);
406	
407	                result_state = queue_iter->hits >= enable_cache_hits_threshold ? FileSegment::State::EMPTY : FileSegment::State::SKIP_CACHE;
408	            }
409	        }
410	
411	        return std::make_shared<FileSegment>(offset, size, key, this, result_state, is_persistent);
412	    };
413	
414	    FileSegmentCell cell(skip_or_download(), this, cache_lock);
415	    auto & offsets = files[key];
416	
417	    if (offsets.empty())
418	    {
419	        auto key_path = getPathInLocalCache(key);
420	        if (!fs::exists(key_path))
421	            fs::create_directories(key_path);
422	    }
423	
424	    auto [it, inserted] = offsets.insert({offset, std::move(cell)});
425	    if (!inserted)
426	        throw Exception(
427	            ErrorCodes::LOGICAL_ERROR,
428	            "Failed to insert into cache key: `{}`, offset: {}, size: {}",
429	            key.toString(), offset, size);
430	
431	    return &(it->second);
432	}
