457	bool LRUFileCache::tryReserve(const Key & key, size_t offset, size_t size, std::lock_guard<std::mutex> & cache_lock)
458	{
459	    auto query_context = enable_filesystem_query_cache_limit ? getCurrentQueryContext(cache_lock) : nullptr;
460	    if (!query_context)
461	        return tryReserveForMainList(key, offset, size, nullptr, cache_lock);
462	
463	    /// The maximum cache capacity of the request is not reached, thus the
464	    //// cache block is evicted from the main LRU queue by tryReserveForMainList().
465	    else if (query_context->getCacheSize() + size <= query_context->getMaxCacheSize())
466	        return tryReserveForMainList(key, offset, size, query_context, cache_lock);
467	
468	    /// When skip_download_if_exceeds_query_cache is true, there is no need
469	    /// to evict old data, skip the cache and read directly from remote fs.
470	    else if (query_context->isSkipDownloadIfExceed())
471	        return false;
472	
473	    /// The maximum cache size of the query is reached, the cache will be
474	    /// evicted from the history cache accessed by the current query.
475	    else
476	    {
477	        size_t removed_size = 0;
478	        size_t queue_size = queue.getElementsNum(cache_lock);
479	
480	        auto * cell_for_reserve = getCell(key, offset, cache_lock);
481	
482	        std::vector<IFileCache::LRUQueue::Iterator> ghost;
483	        std::vector<FileSegmentCell *> trash;
484	        std::vector<FileSegmentCell *> to_evict;
485	
486	        auto is_overflow = [&]
487	        {
488	            return (max_size != 0 && queue.getTotalCacheSize(cache_lock) + size - removed_size > max_size)
489	            || (max_element_size != 0 && queue_size > max_element_size)
490	            || (query_context->getCacheSize() + size - removed_size > query_context->getMaxCacheSize());
491	        };
492	
493	        /// Select the cache from the LRU queue held by query for expulsion.
494	        for (auto iter = query_context->queue().begin(); iter != query_context->queue().end(); iter++)
495	        {
496	            if (!is_overflow())
497	                break;
498	
499	            auto * cell = getCell(iter->key, iter->offset, cache_lock);
500	
501	            if (!cell)
502	            {
503	                /// The cache corresponding to this record may be swapped out by
504	                /// other queries, so it has become invalid.
505	                ghost.push_back(iter);
506	                removed_size += iter->size;
507	            }
508	            else
509	            {
510	                size_t cell_size = cell->size();
511	                assert(iter->size == cell_size);
512	
513	                if (cell->releasable())
514	                {
515	                    auto & file_segment = cell->file_segment;
516	                    std::lock_guard segment_lock(file_segment->mutex);
517	
518	                    switch (file_segment->download_state)
519	                    {
520	                        case FileSegment::State::DOWNLOADED:
521	                        {
522	                            to_evict.push_back(cell);
523	                            break;
524	                        }
525	                        default:
526	                        {
527	                            trash.push_back(cell);
528	                            break;
529	                        }
530	                    }
531	                    removed_size += cell_size;
532	                    --queue_size;
533	                }
534	            }
535	        }
536	
537	        auto remove_file_segment = [&](FileSegmentPtr file_segment, size_t file_segment_size)
538	        {
539	            query_context->remove(file_segment->key(), file_segment->offset(), file_segment_size, cache_lock);
540	
541	            std::lock_guard segment_lock(file_segment->mutex);
542	            remove(file_segment->key(), file_segment->offset(), cache_lock, segment_lock);
543	        };
544	
545	        assert(trash.empty());
546	        for (auto & cell : trash)
547	        {
548	            if (auto file_segment = cell->file_segment)
549	                remove_file_segment(file_segment, cell->size());
550	        }
551	
552	        for (auto & iter : ghost)
553	            query_context->remove(iter->key, iter->offset, iter->size, cache_lock);
554	
555	        if (is_overflow())
556	            return false;
557	
558	        if (cell_for_reserve)
559	        {
560	            auto queue_iterator = cell_for_reserve->queue_iterator;
561	            if (queue_iterator)
562	                queue.incrementSize(*queue_iterator, size, cache_lock);
563	            else
564	                cell_for_reserve->queue_iterator = queue.add(key, offset, size, cache_lock);
565	        }
566	
567	        for (auto & cell : to_evict)
568	        {
569	            if (auto file_segment = cell->file_segment)
570	                remove_file_segment(file_segment, cell->size());
571	        }
572	
573	        query_context->reserve(key, offset, size, cache_lock);
574	        return true;
575	    }
576	}
