578	bool LRUFileCache::tryReserveForMainList(
579	    const Key & key, size_t offset, size_t size, QueryContextPtr query_context, std::lock_guard<std::mutex> & cache_lock)
580	{
581	    auto removed_size = 0;
582	    size_t queue_size = queue.getElementsNum(cache_lock);
583	    assert(queue_size <= max_element_size);
584	
585	    /// Since space reservation is incremental, cache cell already exists if it's state is EMPTY.
586	    /// And it cache cell does not exist on startup -- as we first check for space and then add a cell.
587	    auto * cell_for_reserve = getCell(key, offset, cache_lock);
588	
589	    /// A cell acquires a LRUQueue iterator on first successful space reservation attempt.
590	    /// cell_for_reserve can be nullptr here when we call tryReserve() from loadCacheInfoIntoMemory().
591	    if (!cell_for_reserve || !cell_for_reserve->queue_iterator)
592	        queue_size += 1;
593	
594	    auto is_overflow = [&]
595	    {
596	        /// max_size == 0 means unlimited cache size, max_element_size means unlimited number of cache elements.
597	        return (max_size != 0 && queue.getTotalCacheSize(cache_lock) + size - removed_size > max_size)
598	            || (max_element_size != 0 && queue_size > max_element_size);
599	    };
600	
601	    std::vector<FileSegmentCell *> to_evict;
602	    std::vector<FileSegmentCell *> trash;
603	
604	    for (const auto & [entry_key, entry_offset, entry_size, _] : queue)
605	    {
606	        if (!is_overflow())
607	            break;
608	
609	        auto * cell = getCell(entry_key, entry_offset, cache_lock);
610	        if (!cell)
611	            throw Exception(
612	                ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
613	                "Cache became inconsistent. Key: {}, offset: {}",
614	                key.toString(), offset);
615	
616	        size_t cell_size = cell->size();
617	        assert(entry_size == cell_size);
618	
619	        /// It is guaranteed that cell is not removed from cache as long as
620	        /// pointer to corresponding file segment is hold by any other thread.
621	
622	        if (cell->releasable())
623	        {
624	            auto & file_segment = cell->file_segment;
625	
626	            std::lock_guard segment_lock(file_segment->mutex);
627	
628	            switch (file_segment->download_state)
629	            {
630	                case FileSegment::State::DOWNLOADED:
631	                {
632	                    /// Cell will actually be removed only if
633	                    /// we managed to reserve enough space.
634	
635	                    to_evict.push_back(cell);
636	                    break;
637	                }
638	                default:
639	                {
640	                    trash.push_back(cell);
641	                    break;
642	                }
643	            }
644	
645	            removed_size += cell_size;
646	            --queue_size;
647	        }
648	    }
649	
650	    auto remove_file_segment = [&](FileSegmentPtr file_segment)
651	    {
652	        std::lock_guard segment_lock(file_segment->mutex);
653	        remove(file_segment->key(), file_segment->offset(), cache_lock, segment_lock);
654	    };
655	
656	    /// This case is very unlikely, can happen in case of exception from
657	    /// file_segment->complete(), which would be a logical error.
658	    assert(trash.empty());
659	    for (auto & cell : trash)
660	    {
661	        if (auto file_segment = cell->file_segment)
662	            remove_file_segment(file_segment);
663	    }
664	
665	    if (is_overflow())
666	        return false;
667	
668	    /// cache cell is nullptr on server startup because we first check for space and then add a cell.
669	    if (cell_for_reserve)
670	    {
671	        /// queue_iteratir is std::nullopt here if no space has been reserved yet, a cache cell
672	        /// acquires queue iterator on first successful space reservation attempt.
673	        /// If queue iterator already exists, we need to update the size after each space reservation.
674	        auto queue_iterator = cell_for_reserve->queue_iterator;
675	        if (queue_iterator)
676	            queue.incrementSize(*queue_iterator, size, cache_lock);
677	        else
678	            cell_for_reserve->queue_iterator = queue.add(key, offset, size, cache_lock);
679	    }
680	
681	    for (auto & cell : to_evict)
682	    {
683	        if (auto file_segment = cell->file_segment)
684	            remove_file_segment(file_segment);
685	    }
686	
687	    if (queue.getTotalCacheSize(cache_lock) > (1ull << 63))
688	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Cache became inconsistent. There must be a bug");
689	
690	    if (query_context)
691	        query_context->reserve(key, offset, size, cache_lock);
692	
693	    return true;
694	}
