696	void LRUFileCache::removeIfExists(const Key & key)
697	{
698	    assertInitialized();
699	
700	    std::lock_guard cache_lock(mutex);
701	
702	    auto it = files.find(key);
703	    if (it == files.end())
704	        return;
705	
706	    auto & offsets = it->second;
707	
708	    std::vector<FileSegmentCell *> to_remove;
709	    to_remove.reserve(offsets.size());
710	
711	    for (auto & [offset, cell] : offsets)
712	        to_remove.push_back(&cell);
713	
714	    bool some_cells_were_skipped = false;
715	    for (auto & cell : to_remove)
716	    {
717	        /// In ordinary case we remove data from cache when it's not used by anyone.
718	        /// But if we have multiple replicated zero-copy tables on the same server
719	        /// it became possible to start removing something from cache when it is used
720	        /// by other "zero-copy" tables. That is why it's not an error.
721	        if (!cell->releasable())
722	        {
723	            some_cells_were_skipped = true;
724	            continue;
725	        }
726	
727	        auto file_segment = cell->file_segment;
728	        if (file_segment)
729	        {
730	            std::lock_guard<std::mutex> segment_lock(file_segment->mutex);
731	            file_segment->detach(cache_lock, segment_lock);
732	            remove(file_segment->key(), file_segment->offset(), cache_lock, segment_lock);
733	        }
734	    }
735	
736	    auto key_path = getPathInLocalCache(key);
737	
738	    if (!some_cells_were_skipped)
739	    {
740	        files.erase(key);
741	
742	        if (fs::exists(key_path))
743	            fs::remove_all(key_path);
744	    }
745	}
