747	void LRUFileCache::removeIfReleasable(bool remove_persistent_files)
748	{
749	    /// Try remove all cached files by cache_base_path.
750	    /// Only releasable file segments are evicted.
751	    /// `remove_persistent_files` defines whether non-evictable by some criteria files
752	    /// (they do not comply with the cache eviction policy) should also be removed.
753	
754	    std::lock_guard cache_lock(mutex);
755	
756	    std::vector<FileSegment *> to_remove;
757	    for (auto it = queue.begin(); it != queue.end();)
758	    {
759	        const auto & [key, offset, size, _] = *it++;
760	        auto * cell = getCell(key, offset, cache_lock);
761	        if (!cell)
762	            throw Exception(
763	                ErrorCodes::LOGICAL_ERROR,
764	                "Cache is in inconsistent state: LRU queue contains entries with no cache cell");
765	
766	        if (cell->releasable())
767	        {
768	            auto file_segment = cell->file_segment;
769	            if (file_segment
770	                && (!file_segment->isPersistent()
771	                    || remove_persistent_files
772	                    || allow_to_remove_persistent_segments_from_cache_by_default))
773	            {
774	                std::lock_guard segment_lock(file_segment->mutex);
775	                file_segment->detach(cache_lock, segment_lock);
776	                remove(file_segment->key(), file_segment->offset(), cache_lock, segment_lock);
777	            }
778	        }
779	    }
780	
781	    /// Remove all access information.
782	    records.clear();
783	    stash_queue.removeAll(cache_lock);
784	
785	#ifndef NDEBUG
786	    assertCacheCorrectness(cache_lock);
787	#endif
788	}
