790	void LRUFileCache::remove(
791	    Key key, size_t offset,
792	    std::lock_guard<std::mutex> & cache_lock, std::lock_guard<std::mutex> & /* segment_lock */)
793	{
794	    LOG_TEST(log, "Remove. Key: {}, offset: {}", key.toString(), offset);
795	
796	    auto * cell = getCell(key, offset, cache_lock);
797	    if (!cell)
798	        throw Exception(ErrorCodes::LOGICAL_ERROR, "No cache cell for key: {}, offset: {}", key.toString(), offset);
799	
800	    bool is_persistent_file_segment = cell->file_segment->isPersistent();
801	
802	    if (cell->queue_iterator)
803	    {
804	        queue.remove(*cell->queue_iterator, cache_lock);
805	    }
806	
807	    auto & offsets = files[key];
808	    offsets.erase(offset);
809	
810	    auto cache_file_path = getPathInLocalCache(key, offset, is_persistent_file_segment);
811	    if (fs::exists(cache_file_path))
812	    {
813	        try
814	        {
815	            fs::remove(cache_file_path);
816	
817	            if (is_initialized && offsets.empty())
818	            {
819	                auto key_path = getPathInLocalCache(key);
820	
821	                files.erase(key);
822	
823	                if (fs::exists(key_path))
824	                    fs::remove_all(key_path);
825	            }
826	        }
827	        catch (...)
828	        {
829	            throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
830	                            "Removal of cached file failed. Key: {}, offset: {}, path: {}, error: {}",
831	                            key.toString(), offset, cache_file_path, getCurrentExceptionMessage(false));
832	        }
833	    }
834	}
