836	void LRUFileCache::loadCacheInfoIntoMemory(std::lock_guard<std::mutex> & cache_lock)
837	{
838	    Key key;
839	    UInt64 offset = 0;
840	    size_t size = 0;
841	    std::vector<std::pair<LRUQueue::Iterator, std::weak_ptr<FileSegment>>> queue_entries;
842	
843	    /// cache_base_path / key_prefix / key / offset
844	
845	    if (!files.empty())
846	        throw Exception(
847	            ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
848	            "Cache initialization is partially made. "
849	            "This can be a result of a failed first attempt to initialize cache. "
850	            "Please, check log for error messages");
851	
852	    fs::directory_iterator key_prefix_it{cache_base_path};
853	    for (; key_prefix_it != fs::directory_iterator(); ++key_prefix_it)
854	    {
855	        fs::directory_iterator key_it{key_prefix_it->path()};
856	        for (; key_it != fs::directory_iterator(); ++key_it)
857	        {
858	            key = Key(unhexUInt<UInt128>(key_it->path().filename().string().data()));
859	
860	            fs::directory_iterator offset_it{key_it->path()};
861	            for (; offset_it != fs::directory_iterator(); ++offset_it)
862	            {
863	                auto offset_with_suffix = offset_it->path().filename().string();
864	                auto delim_pos = offset_with_suffix.find('_');
865	                bool parsed;
866	                bool is_persistent = false;
867	
868	                if (delim_pos == std::string::npos)
869	                    parsed = tryParse<UInt64>(offset, offset_with_suffix);
870	                else
871	                {
872	                    parsed = tryParse<UInt64>(offset, offset_with_suffix.substr(0, delim_pos));
873	                    is_persistent = offset_with_suffix.substr(delim_pos+1) == "persistent";
874	                }
875	
876	                if (!parsed)
877	                {
878	                    LOG_WARNING(log, "Unexpected file: ", offset_it->path().string());
879	                    continue; /// Or just remove? Some unexpected file.
880	                }
881	
882	                size = offset_it->file_size();
883	                if (!size)
884	                {
885	                    fs::remove(offset_it->path());
886	                    continue;
887	                }
888	
889	                if (tryReserve(key, offset, size, cache_lock))
890	                {
891	                    auto * cell = addCell(key, offset, size, FileSegment::State::DOWNLOADED, is_persistent, cache_lock);
892	                    if (cell)
893	                        queue_entries.emplace_back(*cell->queue_iterator, cell->file_segment);
894	                }
895	                else
896	                {
897	                    LOG_WARNING(log,
898	                                "Cache capacity changed (max size: {}, available: {}), cached file `{}` does not fit in cache anymore (size: {})",
899	                                max_size, getAvailableCacheSizeUnlocked(cache_lock), key_it->path().string(), size);
900	                    fs::remove(offset_it->path());
901	                }
902	            }
903	        }
904	    }
905	
906	    /// Shuffle cells to have random order in LRUQueue as at startup all cells have the same priority.
907	    pcg64 generator(randomSeed());
908	    std::shuffle(queue_entries.begin(), queue_entries.end(), generator);
909	    for (const auto & [it, file_segment] : queue_entries)
910	    {
911	        /// Cell cache size changed and, for example, 1st file segment fits into cache
912	        /// and 2nd file segment will fit only if first was evicted, then first will be removed and
913	        /// cell is nullptr here.
914	        if (file_segment.expired())
915	            continue;
916	
917	        queue.moveToEnd(it, cache_lock);
918	    }
919	#ifndef NDEBUG
920	    assertCacheCorrectness(cache_lock);
921	#endif
922	}
