924	void LRUFileCache::reduceSizeToDownloaded(
925	    const Key & key, size_t offset,
926	    std::lock_guard<std::mutex> & cache_lock, std::lock_guard<std::mutex> & /* segment_lock */)
927	{
928	    /**
929	     * In case file was partially downloaded and it's download cannot be continued
930	     * because of no space left in cache, we need to be able to cut cell's size to downloaded_size.
931	     */
932	
933	    auto * cell = getCell(key, offset, cache_lock);
934	
935	    if (!cell)
936	    {
937	        throw Exception(
938	            ErrorCodes::LOGICAL_ERROR,
939	            "No cell found for key: {}, offset: {}",
940	            key.toString(), offset);
941	    }
942	
943	    const auto & file_segment = cell->file_segment;
944	
945	    size_t downloaded_size = file_segment->downloaded_size;
946	    if (downloaded_size == file_segment->range().size())
947	    {
948	        throw Exception(
949	            ErrorCodes::LOGICAL_ERROR,
950	            "Nothing to reduce, file segment fully downloaded, key: {}, offset: {}",
951	            key.toString(), offset);
952	    }
953	
954	    cell->file_segment = std::make_shared<FileSegment>(offset, downloaded_size, key, this, FileSegment::State::DOWNLOADED);
955	}
