1034	LRUFileCache::FileSegmentCell::FileSegmentCell(
1035	    FileSegmentPtr file_segment_,
1036	    LRUFileCache * cache,
1037	    std::lock_guard<std::mutex> & cache_lock)
1038	    : file_segment(file_segment_)
1039	{
1040	    /**
1041	     * Cell can be created with either DOWNLOADED or EMPTY file segment's state.
1042	     * File segment acquires DOWNLOADING state and creates LRUQueue iterator on first
1043	     * successful getOrSetDownaloder call.
1044	     */
1045	
1046	    switch (file_segment->download_state)
1047	    {
1048	        case FileSegment::State::DOWNLOADED:
1049	        {
1050	            queue_iterator = cache->queue.add(file_segment->key(), file_segment->offset(), file_segment->range().size(), cache_lock);
1051	            break;
1052	        }
1053	        case FileSegment::State::SKIP_CACHE:
1054	        case FileSegment::State::EMPTY:
1055	        case FileSegment::State::DOWNLOADING:
1056	        {
1057	            break;
1058	        }
1059	        default:
1060	            throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
1061	                            "Can create cell with either EMPTY, DOWNLOADED, DOWNLOADING state, got: {}",
1062	                            FileSegment::stateToString(file_segment->download_state));
1063	    }
1064	}
